## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;
  localparam int BIT_CLKS = int'(PRESCALE) * 8;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  wire         s_axis_tready;
  wire [7:0]   m_axis_tdata;
  wire         m_axis_tvalid;
  logic        m_axis_tready = 1'b1;
  logic        rxd = 1'b1;
  wire         txd;
  logic [15:0] prescale = PRESCALE;
  wire         tx_busy, rx_busy, rx_overrun_error, rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk), .rst(rst),
    .s_axis_tdata(s_axis_tdata), .s_axis_tvalid(s_axis_tvalid), .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid), .m_axis_tready(m_axis_tready),
    .rxd(rxd), .txd(txd),
    .tx_busy(tx_busy), .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error), .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_negedges(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic drive_rxd(input logic val, input int nclks);
    rxd = val;
    wait_negedges(nclks);
  endtask

  task automatic send_byte(input logic [7:0] data);
    drive_rxd(1'b0, BIT_CLKS);
    for (int i = 0; i < 8; i++)
      drive_rxd(data[i], BIT_CLKS);
    drive_rxd(1'b1, BIT_CLKS);
  endtask

  initial begin
    rst = 1'b1;
    wait_negedges(4);
    rst = 1'b0;
    wait_negedges(4);

    // Back-to-back frames with no inter-frame gap:
    // first byte 0x00, second byte 0x5A
    send_byte(8'h00);
    send_byte(8'h5A);

    // Wait for first byte delivery
    @(posedge m_axis_tvalid);
    @(negedge clk);

    // Wait for second byte delivery
    @(posedge m_axis_tvalid);
    @(negedge clk);

    if (m_axis_tdata !== 8'h5A) begin
      $display("FAIL: second byte 0x%02h, expected 0x5A", m_axis_tdata);
      $finish;
    end
    if (rx_frame_error) begin
      $display("FAIL: frame error detected");
      $finish;
    end

    $display("PASS R14: back-to-back 0x00 then 0x5A received");
    $finish;
  end

  initial begin
    #50ms;
    $display("FAIL: timeout");
    $finish;
  end

endmodule
```

